def separate_paren_groups(paren_string: str) -> list:
    paren_string = paren_string.replace(" ", "")

    groups = []
    current_group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        current_group += char

        if open_count == 0:
            groups.append(current_group)
            current_group = ""

    separated_groups = [group for group in groups if group != ""]

    return separated_groups

